import { test, expect } from '@playwright/test';

test.describe('CSV Import Feature', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records/import');
  });

  test('should successfully import records from a valid CSV file', async ({ page }) => {
    // Setup: intercept the import API call
    await page.route('**/api/records/import', (route) => {
      route.continue();
    });

    // Verify import button is visible
    const importButton = page.getByRole('button', { name: /import csv/i });
    await expect(importButton).toBeVisible();

    // Verify import file input is visible
    const fileInput = page.getByLabel(/csv file/i);
    await expect(fileInput).toBeVisible();

    // Verify import success message is visible
    const successMessage = page.getByText(/records imported successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify records are listed
    const recordsList = page.getByRole('list', { name: /records/i });
    await expect(recordsList).toBeVisible();

    // Verify record count is displayed
    const recordCount = page.getByText(/records imported/i);
    await expect(recordCount).toBeVisible();

    // Verify import button is disabled after successful import
    await expect(importButton).toBeDisabled();

    // Verify import button is visible again after clearing the file input
    await fileInput.fill('valid.csv');
    await importButton.click();
    await expect(importButton).toBeVisible();

    // Verify success message is cleared
    await expect(successMessage).not.toBeVisible();

    // Verify file input is cleared
    await expect(fileInput).toHaveValue('');
  });

  test('should display error when importing an invalid CSV file', async ({ page }) => {
    // Setup: intercept the import API call with error response
    await page.route('**/api/records/import', (route) => {
      route.abort('failed');
    });

    // Verify import button is visible
    const importButton = page.getByRole('button', { name: /import csv/i });
    await expect(importButton).toBeVisible();

    // Verify import file input is visible
    const fileInput = page.getByLabel(/csv file/i);
    await expect(fileInput).toBeVisible();

    // Verify error message is visible
    const errorMessage = page.getByText(/failed to import/i);
    await expect(errorMessage).toBeVisible();

    // Verify import button is disabled after failed import
    await expect(importButton).toBeDisabled();

    // Verify file input is still visible
    await expect(fileInput).toHaveValue('');

    // Verify error message is cleared after clearing the file input
    await fileInput.fill('invalid.csv');
    await importButton.click();
    await expect(errorMessage).not.toBeVisible();

    // Verify success message is not displayed
    const successMessage = page.getByText(/records imported successfully/i);
    await expect(successMessage).not.toBeVisible();

    // Verify import button is visible again
    await expect(importButton).toBeVisible();
  });
});
